100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        String normalizedAddress = normalizeAddress(owner.getAddress());
106	        if (normalizedAddress.isEmpty()) {
107	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
108	                "Address must not be blank after normalization");
109	        }
110	        owner.setAddress(normalizedAddress);
111	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
112	        owner.setTelephone(normalizedTelephone);
113	        owner.setEmail(normalizeEmail(owner.getEmail()));
114	        if (owner.getRegistrationDate() == null) {
115	            owner.setRegistrationDate(java.time.LocalDate.now());
116	        }
117	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
118	            .map(Owner::getTelephone)
119	            .filter(java.util.Objects::nonNull)
120	            .anyMatch(normalizedTelephone::equals);
121	        if (telephoneInUse) {
122	            throw new ResponseStatusException(HttpStatus.CONFLICT,
123	                "An owner with this telephone number already exists");
124	        }
125	        String lastNameKey = normalizeForHousehold(owner.getLastName());
126	        String addressKey = normalizeForHousehold(owner.getAddress());
127	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
128	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
129	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
130	            .toList();
131	        if (!householdMembers.isEmpty()) {
132	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
133	                throw new ResponseStatusException(HttpStatus.CONFLICT,
134	                    "An owner with this last name already exists at this address");
135	            }
136	            String householdId = householdId(lastNameKey, addressKey);
137	            owner.setHouseholdId(householdId);
138	            for (Owner member : householdMembers) {
139	                if (!householdId.equals(member.getHouseholdId())) {
140	                    member.setHouseholdId(householdId);
141	                    this.clinicService.saveOwner(member);
142	                }
143	            }
144	        }
145	        String cityKey = normalizeForHousehold(owner.getCity());
146	        long cityCount = this.clinicService.findAllOwners().stream()
147	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
148	            .count();
149	        if (cityCount >= 50) {
150	            throw new ResponseStatusException(HttpStatus.CONFLICT,
151	                "This city already has the maximum number of owners");
152	        }
153	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
154	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
155	        this.clinicService.saveOwner(owner);
156	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    /**
163	     * Counts the owners that already exist (before the current create) whose first and last names
164	     * both match the supplied names, compared case-insensitively. The returned value is captured on
165	     * the new owner at creation time and does not change as further owners are added later.
166	     *
167	     * @param firstName the new owner's first name
168	     * @param lastName  the new owner's last name
169	     * @return the number of pre-existing namesake owners
170	     */
171	    private int namesakeCount(String firstName, String lastName) {
172	        return (int) this.clinicService.findAllOwners().stream()
173	            .filter(existing -> existing.getFirstName() != null
174	                && existing.getFirstName().equalsIgnoreCase(firstName)
175	                && existing.getLastName() != null
176	                && existing.getLastName().equalsIgnoreCase(lastName))
177	            .count();
178	    }
179	
180	    /**
181	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
182	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} is the
183	     * upper-cased first three letters of the last name, and {@code NNNN} is a per-city 4-digit
184	     * zero-padded sequence equal to one more than the number of owners already in that city
185	     * (e.g. {@code 'SYD-SMI-0007'}).
186	     *
187	     * @param city     the owner's city
188	     * @param lastName the owner's last name
189	     * @return the assigned customer code
190	     */
191	    private String nextCustomerCode(String city, String lastName) {
192	        String cityPrefix = first3Upper(city);
193	        String lastPrefix = first3Upper(lastName);
194	        String cityKey = normalizeForHousehold(city);
195	        long sequence = this.clinicService.findAllOwners().stream()
196	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
197	            .count() + 1L;
198	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
199	    }
200	
201	    /**
202	     * Returns the upper-cased first three characters of {@code value}, or fewer if the value is
203	     * shorter. A {@code null} value yields the empty string.
204	     *
205	     * @param value the source value
206	     * @return the upper-cased first three characters
207	     */
208	    private String first3Upper(String value) {
209	        String v = (value == null ? "" : value);
210	        return v.substring(0, Math.min(3, v.length())).toUpperCase(java.util.Locale.ROOT);
211	    }
212	
213	    /**
214	     * Normalizes a street address applied whenever an owner is created: leading and trailing
215	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
216	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
217	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
218	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
219	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
220	     * {@code '12 MAIN STREET'}.
221	     *
222	     * @param address the raw address as submitted, or {@code null} when absent
223	     * @return the normalized address, or the empty string when the value is blank
224	     */
225	    private String normalizeAddress(String address) {
226	        String collapsed = (address == null ? "" : address)
227	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
228	        if (collapsed.isEmpty()) {
229	            return "";
230	        }
231	        String[] tokens = collapsed.split(" ");
232	        for (int i = 0; i < tokens.length; i++) {
233	            switch (tokens[i]) {
234	                case "ST" -> tokens[i] = "STREET";
235	                case "RD" -> tokens[i] = "ROAD";
236	                case "AVE" -> tokens[i] = "AVENUE";
237	                default -> { }
238	            }
239	        }
240	        return String.join(" ", tokens);
241	    }
242	
243	    /**
244	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
245	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
246	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
247	     * empty string.
248	     *
249	     * @param value the raw value (last name or address) as submitted
250	     * @return the normalized comparison key
251	     */
252	    private String normalizeForHousehold(String value) {
253	        if (value == null) {
254	            return "";
255	        }
256	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
257	    }
258	
259	    /**
260	     * Derives the stable shared household identifier for a household, keyed on the normalized last
261	     * name and address. Because it is a pure function of those normalized keys, every owner in the
262	     * same household deterministically computes the same value. The identifier is the first 12
263	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
264	     * (the separator prevents distinct name/address pairs from colliding).
265	     *
266	     * @param lastNameKey the normalized last-name comparison key
267	     * @param addressKey  the normalized address comparison key
268	     * @return the stable household identifier
269	     */
270	    private String householdId(String lastNameKey, String addressKey) {
271	        String seed = lastNameKey + "�" + addressKey;
272	        try {
273	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
274	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
275	            StringBuilder sb = new StringBuilder(digest.length * 2);
276	            for (byte b : digest) {
277	                sb.append(String.format("%02x", b));
278	            }
279	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
280	        }
281	        catch (java.security.NoSuchAlgorithmException e) {
282	            throw new IllegalStateException("SHA-256 not available", e);
283	        }
284	    }
285	
286	    /**
287	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
288	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
289	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
290	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
291	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
292	     * is stored as {@code '+61412345678'}.
293	     *
294	     * @param telephone the raw telephone number as submitted
295	     * @return the normalized E.164 telephone number
296	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
297	     *         number (8 to 15 digits after the '+')
298	     */
299	    private String normalizeTelephone(String telephone) {
300	        String raw = telephone == null ? "" : telephone.trim();
301	        String digits = raw.replaceAll("\\D", "");
302	        String e164;
303	        if (raw.startsWith("+")) {
304	            e164 = "+" + digits;
305	        } else {
306	            if (digits.startsWith("0")) {
307	                digits = digits.substring(1);
308	            }
309	            e164 = "+61" + digits;
310	        }
311	        int digitCount = e164.length() - 1;
312	        if (digitCount < 8 || digitCount > 15) {
313	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
314	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
315	        }
316	        return e164;
317	    }
318	
319	    /**
320	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
321	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
322	     * (absent) or already valid.
323	     *
324	     * @param email the email address as submitted, or {@code null} when absent
325	     * @return the lower-cased email, or {@code null} when absent
326	     */
327	    private String normalizeEmail(String email) {
328	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
329	    }
330	
331	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
332	    @Override
