340	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
341	        currentOwner.setLastName(ownerFieldsDto.getLastName());
342	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
343	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
344	        this.clinicService.saveOwner(currentOwner);
345	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
346	    }
