355	        }
356	        this.clinicService.deleteOwner(owner);
357	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
358	    }
359	
360	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
361	    @Override
362	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
363	        Owner owner = this.clinicService.findOwnerById(ownerId);
364	        if (owner == null) {
365	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
366	        }
367	        HttpHeaders headers = new HttpHeaders();
368	        Pet pet = petMapper.toPet(petFieldsDto);
369	        owner.setId(ownerId);
370	        pet.setOwner(owner);
371	        pet.getType().setName(null);
372	        this.clinicService.savePet(pet);
373	        PetDto petDto = petMapper.toPetDto(pet);
374	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
375	            .buildAndExpand(pet.getId()).toUri());
376	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
377	    }
378	
379	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
380	    @Override
381	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
382	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
383	        if (currentOwner != null) {
384	            Pet currentPet = this.clinicService.findPetById(petId);
385	            if (currentPet != null) {
386	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
387	                currentPet.setName(petFieldsDto.getName());
388	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
389	                this.clinicService.savePet(currentPet);
390	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
391	            }
392	        }
393	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
394	    }
