42	/**
43	 * Global Exception handler for REST controllers.
44	 * <p>
45	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
46	 *
47	 * @author Vitaliy Fedoriv
48	 * @author Alexander Dudkin
49	 */
50	@ControllerAdvice
51	public class ExceptionControllerAdvice {
52	
53	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
54	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
55	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
56	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
57	
58	    /**
59	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
60	     * class.
61	     *
62	     * @param e     Object referring to the thrown exception.
63	     * @param status HTTP response status.
64	     * @param url URL request.
65	     */
66	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
67	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
68	        problemDetail.setType(URI.create(url.toString()));
69	        problemDetail.setTitle(e.getClass().getSimpleName());
70	        problemDetail.setDetail(detail);
71	        problemDetail.setProperty("timestamp", Instant.now());
72	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
73	        return problemDetail;
74	    }
75	
76	    /**
77	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
78	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
79	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
80	     * would catch it and report an authorization failure as a 500.
81	     *
82	     * @param e The {@link AccessDeniedException} to propagate
83	     * @throws AccessDeniedException always
84	     */
85	    @ExceptionHandler(AccessDeniedException.class)
86	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
87	        throw e;
88	    }
89	
90	    /**
91	     * Handles {@link ResponseStatusException} thrown by controllers to signal a specific HTTP status
92	     * (e.g. a 400 Bad Request for a business-rule violation). Without this handler the broad
93	     * {@link #handleGeneralException} would catch it first and report it as a 500.
94	     *
95	     * @param e The {@link ResponseStatusException} to be handled
96	     * @param request {@link HttpServletRequest} object referring to the current request.
97	     * @return A {@link ResponseEntity} carrying the status and reason from the exception.
98	     */
99	    @ExceptionHandler(ResponseStatusException.class)
100	    @ResponseBody
101	    public ResponseEntity<ProblemDetail> handleResponseStatusException(ResponseStatusException e, HttpServletRequest request) {
102	        HttpStatus status = HttpStatus.valueOf(e.getStatusCode().value());
103	        String detailMessage = e.getReason() != null ? e.getReason() : ERROR_INVALID_REQUEST;
104	        logger.warn("Request failed at {} {}: {}", request.getMethod(), request.getRequestURI(), detailMessage);
105	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), detailMessage);
106	        return ResponseEntity.status(status).body(detail);
107	    }
108	
109	    /**
110	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
111	     *
112	     * @param e The {@link Exception} to be handled
113	     * @param request {@link HttpServletRequest} object referring to the current request.
114	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
115	     */
116	    @ExceptionHandler(Exception.class)
117	    @ResponseBody
118	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
119	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
120	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
121	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
122	        return ResponseEntity.status(status).body(detail);
123	    }
124	
125	    /**
126	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
127	     * method returns a 404 Not Found status if an entity does not exist.
128	     *
129	     * @param e The {@link DataIntegrityViolationException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
132	     */
133	    @ExceptionHandler(DataIntegrityViolationException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
136	        logger.warn("Data integrity violation at {} {}: {}",
137	            request.getMethod(),
138	            request.getRequestURI(),
139	            e.getMessage());
140	        logger.debug("Data integrity violation stacktrace", e);
141	        HttpStatus status = HttpStatus.NOT_FOUND;
142	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
143	        return ResponseEntity.status(status).body(detail);
144	    }
145	
146	    /**
147	     * Handles exception thrown by Bean Validation on controller methods parameters
148	     *
149	     * @param e The {@link MethodArgumentNotValidException} to be handled
150	     * @param request {@link HttpServletRequest} object referring to the current request.
151	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
152	     */
153	    @ExceptionHandler(MethodArgumentNotValidException.class)
154	    @ResponseBody
155	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
156	        HttpStatus status = HttpStatus.BAD_REQUEST;
157	        BindingErrorsResponse errors = new BindingErrorsResponse();
158	        BindingResult bindingResult = e.getBindingResult();
159	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
160	        detail.setProperty("errors", List.<String>of());
161	        if (bindingResult.hasErrors()) {
162	            errors.addAllErrors(bindingResult);
163	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
164	                .map(FieldError::getField)
165	                .distinct()
166	                .toList();
167	            detail.setProperty("errors", invalidFields);
168	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
169	                .map(fieldError -> {
170	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
171	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
172	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
173	                        fieldError.getField(),
174	                        defaultMessage,
175	                        rejectedValue);
176	                    return new ValidationMessageDto(message)
177	                        .putAdditionalProperty("field", fieldError.getField())
178	                        .putAdditionalProperty("rejectedValue", rejectedValue)
179	                        .putAdditionalProperty("defaultMessage", defaultMessage);
180	                })
181	                .toList();
182	            logger.debug("Validation error at {} {}: {}",
183	                request.getMethod(),
184	                request.getRequestURI(),
185	                bindingResult.getFieldErrors());
186	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
187	            return ResponseEntity.status(status).body(detail);
188	        }
189	        return ResponseEntity.status(status).body(detail);
190	    }
